SELECT CASE WHEN unit_price >= 320 THEN 'LARGE' ELSE 'SMALL' END AS unit_price_tier, STDDEV_SAMP(quantity) AS quantity_stddev, COUNT(DISTINCT order_id) AS distinct_order_ids, COUNT(DISTINCT id) AS distinct_ids, CORR(quantity, unit_price) AS corr_quantity_unit_price, COUNT(*) AS event_count, ROUND(AVG(unit_price), 2) AS avg_unit_price FROM order_items GROUP BY ROLLUP (CASE WHEN unit_price >= 320 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY corr_quantity_unit_price
